/*
 * A191110  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x and 3x+2 are in a.
 * https://oeis.org/A191110
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 35, u16 n <= 1266, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A191110: a(1)=1; for n>1, a(n) is the n-th integer whose base‑3
   representation consists of a leading 1 followed only by digits 0 or 2
   (obtained by repeatedly appending 0 or 2 in base 3). */
#include <stdint.h>

/* return the number of bits needed to represent x (x>0) */
static inline idx_t bit_length(idx_t x)
{
    idx_t len = 0;
    while (x) {
        x >>= 1;
        len++;
    }
    return len;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* undefined, safeguard */

    /* Determine the length L of the base‑3 representation:
       count of terms up to length L equals 2^L – 1, so L = bit_length(n). */
    idx_t L = bit_length(n);

    /* Offset within all numbers of length L (0‑based). */
    idx_t offset = n - ((idx_t)1 << (L - 1));

    /* Construct the number by appending (L‑1) digits from most significant
       to least: each bit of 'offset' decides whether that digit is 0 or 2. */
    seq_t val = 1;                 /* leading digit 1 */
    for (idx_t i = 0; i < L - 1; ++i) {
        val = val * 3;             /* shift left in base 3 */
        if (offset & ((idx_t)1 << ((L - 2) - i)))
            val += 2;             /* add digit 2 for a bit '1' */
    }
    return val;
}
